// Alertmanager webhook payload (version 4): { status, receiver, groupLabels, commonLabels, alerts: [...] }
// One output item per alert, normalised for the ticketing / notification steps.
const payload = $input.first().json.body ?? {};
const alerts = Array.isArray(payload.alerts) ? payload.alerts : [];

const problemTitles = {
  high_latency: 'High Latency',
  high_error_rate: 'High Error Rate',
  service_down: 'Service Down',
};

return alerts.map(a => {
  const labels = a.labels ?? {};
  const annotations = a.annotations ?? {};
  const service = labels.service || labels.job || 'unknown-service';
  const problem = labels.problem || labels.alertname;
  return {
    json: {
      fingerprint: a.fingerprint,
      status: a.status,                              // "firing" | "resolved"
      alertName: labels.alertname,
      problemType: problemTitles[problem] ?? labels.alertname,
      service,
      instance: labels.instance ?? null,
      severity: labels.severity ?? 'warning',
      summary: annotations.summary ?? labels.alertname,
      description: annotations.description ?? '',
      startsAt: a.startsAt,
      endsAt: a.status === 'resolved' ? a.endsAt : null,
      prometheusUrl: a.generatorURL,
      receivedAt: new Date().toISOString(),
    },
  };
});

// Jira imitation: creates an incident ticket for a firing alert and resolves the SAME ticket when the
// alert resolves. Tickets are keyed by the Alertmanager fingerprint and kept in workflow static data
// (persisted by n8n for active workflows; manual test runs start with an empty store).
const store = $getWorkflowStaticData('global');
store.tickets = store.tickets ?? {};
store.seq = store.seq ?? 0;

const grafana = $env.GRAFANA_URL || 'http://localhost:3001';
const jaeger = $env.JAEGER_URL || 'http://localhost:16686';
const priority = { critical: 'P1 - Highest', warning: 'P2 - High', info: 'P3 - Medium' };

return $input.all().map(({ json: a }) => {
  let ticket = store.tickets[a.fingerprint];
  let action;

  if (a.status === 'firing') {
    if (ticket && ticket.status !== 'Resolved') {
      action = 'updated';                          // Alertmanager repeat notification for an open incident
      ticket.lastSeenAt = a.receivedAt;
      ticket.occurrences += 1;
    } else {
      action = 'created';
      store.seq += 1;
      ticket = {
        key: `MEDOPS-${String(store.seq).padStart(4, '0')}`,
        project: 'MEDOPS',
        issueType: 'Incident',
        status: 'Open',
        priority: priority[a.severity] ?? 'P3 - Medium',
        summary: `[${a.severity.toUpperCase()}] ${a.problemType}: ${a.service}`,
        description: a.description,
        labels: ['aiops', 'auto-created', a.service, a.alertName],
        component: a.service,
        createdAt: a.receivedAt,
        lastSeenAt: a.receivedAt,
        occurrences: 1,
        links: {
          dashboard: `${grafana}/d/medstorage-overview?var-service=${encodeURIComponent(a.service)}`,
          traces: `${jaeger}/search?service=${encodeURIComponent(a.service)}&lookback=1h`,
          prometheus: a.prometheusUrl,
        },
      };
    }
  } else {
    action = ticket ? 'resolved' : 'resolved-untracked';
    ticket = ticket ?? { key: '(none)', summary: `${a.problemType}: ${a.service}`, links: {} };
    ticket.status = 'Resolved';
    ticket.resolvedAt = a.endsAt ?? a.receivedAt;
  }
  if (ticket.key !== '(none)') store.tickets[a.fingerprint] = ticket;

  const icon = a.status === 'firing' ? (a.severity === 'critical' ? ':red_circle:' : ':large_orange_circle:') : ':white_check_mark:';
  const slackText = [
    `${icon} *${ticket.key}* ${action.toUpperCase()} - ${ticket.summary}`,
    a.status === 'firing' ? `> ${a.description}` : `> Resolved at ${ticket.resolvedAt}`,
    a.instance ? `Instance: \`${a.instance}\`` : null,
    ticket.links.dashboard ? `<${ticket.links.dashboard}|Grafana> | <${ticket.links.traces}|Jaeger traces>` : null,
  ].filter(Boolean).join('\n');

  return { json: { action, ticket, alert: a, slackText } };
});
